"""Readability scorer with an explicit syllable heuristic."""

import re

VOWELS = set("aeiouy")
_WORD_RE = re.compile(r"[A-Za-z']+")
_SENTENCE_END_RE = re.compile(r"[.!?]")


def count_syllables(word):
    """Count syllables using these exact rules:

    1. Lowercase the word.
    2. Count maximal runs of vowels (a, e, i, o, u, y) as one syllable each.
    3. Subtract one if the word ends in a silent 'e' (ends with 'e' but not
       an 'le' preceded by a consonant).
    4. Minimum of 1.
    """
    w = word.lower()
    count = 0
    prev_vowel = False
    for ch in w:
        is_vowel = ch in VOWELS
        if is_vowel and not prev_vowel:
            count += 1
        prev_vowel = is_vowel

    # Silent 'e': ends with 'e', unless it's 'le' preceded by a consonant.
    if w.endswith("e"):
        is_le_consonant = (
            len(w) >= 3 and w[-2] == "l" and w[-3].isalpha() and w[-3] not in VOWELS
        )
        if not is_le_consonant:
            count -= 1

    return max(1, count)


def words(text):
    """Maximal runs of letters/apostrophes."""
    return _WORD_RE.findall(text)


def sentences(text):
    """Number of sentence-ending punctuation marks (. ! ?)."""
    return max(1, len(_SENTENCE_END_RE.findall(text)))


def count_syllables_in_text(text):
    return sum(count_syllables(w) for w in words(text))


def flesch(text):
    """Flesch Reading Ease score."""
    n_words = len(words(text))
    n_sents = sentences(text)
    n_sylls = count_syllables_in_text(text)
    return 206.835 - 1.015 * (n_words / n_sents) - 84.6 * (n_sylls / n_words)


def fk_grade(text):
    """Flesch-Kincaid Grade Level."""
    n_words = len(words(text))
    n_sents = sentences(text)
    n_sylls = count_syllables_in_text(text)
    return 0.39 * (n_words / n_sents) + 11.8 * (n_sylls / n_words) - 15.59

